<template><section class="readout-strip" aria-label="Live readout"><div><span>Area signal</span><b>{{ format(currentSignal,0) }} px</b></div><div><span>Elapsed</span><b>{{ duration }}</b></div><div><span>Samples</span><b>{{ sampleCount }}</b></div><div><span>Phase</span><b>{{ phaseText }}</b></div></section></template>
<script setup>import{computed}from'vue';const props=defineProps({currentSignal:Number,elapsedMs:Number,sampleCount:Number,phaseText:String});const duration=computed(()=>`${(props.elapsedMs/1000).toFixed(1)} s`);function format(value,digits){return Number.isFinite(value)?value.toFixed(digits):'--';}</script>
